import numpy as np,random
p=Path('experiments/e1/agent1_compact_D7_conflict_certificate.py');d={'__name__':'audit'};exec(compile(p.read_text(),str(p),'exec'),d)
S,E,words=d['scalar'](7,3);N,inds,ws=d['adjoints'](S,words);m=len(ws);IX={w:i for i,w in enumerate(ws)}
lam=np.zeros(3*m,dtype=np.int64)
for out,w,c in d['FUNCTIONAL']:lam[out*m+IX[tuple(map(int,w))]]=c
C=d['comm'];ev=d['evaluate'];random.seed(1)
for trial in range(300):
 args=[tuple(random.choice(list(S)) for _ in range(random.randint(1,4))) for _ in range(5)]
 w=args[0]
 for a in args[1:]:w=C(w,a)
 v=ev(w,S,E,3)[inds].T.reshape(-1)
 value=int(lam@v%3)
 if value:
  print('FAIL gamma5 at trial',trial,'args',args,'lambda',value);break
else:print('all 300 random gamma5 words annihilated')

